float shadow(vec2 p, vec2 pos, float radius)
{
    vec2 dir = normalize(pos - p);
    float dl = length(p - pos);

    // fraction of light still visible; starts as one radius (the other half is added at the end)
    float lf = radius * dl;

    // distance traveled along the ray
    float dt = 0.01;

    for (int i = 0; i < 64; ++i)
    { 
        // signed distance to the scene from the current sample point
        float sd = sceneDist(p + dir * dt);

        // exit early if this ray is certain to be fully in shadow
        if (sd < -radius) 
            return 0.0;

        // cone overlap width at the light
        // zero at the center; to get 50% overlap we add one radius outside the loop for total coverage
        // this should be '(sd / dt) * dl', but the '* dl' is applied after the loop
        lf = min(lf, sd / dt);

        // advance along the ray
        dt += max(1.0, abs(sd));
        if (dt > dl) break;
    }

    // multiply by dl to obtain the actual projected overlap (moved out of the loop)
    // add one radius to cover values between -radius and +radius
    // normalize to [0, 1] by dividing by (2 * radius)
    lf = clamp((lf * dl + radius) / (2.0 * radius), 0.0, 1.0);
    lf = smoothstep(0.0, 1.0, lf);
    return lf;
}

